const state={data:null,selected:null,filter:'all',leafletMap:null,leafletLayer:null,mapFitted:false};
const $=s=>document.querySelector(s);
const fmt=n=>n==null?'—':new Intl.NumberFormat('en-US',{maximumFractionDigits:1}).format(n);
function renderStats(a){const q=[['qualified_runs','Qualified GPS runs',a.qualified_runs],['published_corridors','Screened corridors',a.published_corridors],['positions','Raw positions',a.positions],['vehicle_activities','Vehicle segments',a.vehicle_activities],['tms_miami_rows','Miami TMS records',a.gis_context?.tms_miami_rows],['count_station_aadt_rows','2019 AADT stations',a.gis_context?.count_station_aadt_rows]];$('#stats').innerHTML=q.map(x=>`<div class="stat"><div class="value">${fmt(x[2])}</div><div class="label">${x[1]}</div></div>`).join('');if($('#period')) $('#period').textContent=`${a.analysis_period.start.slice(0,10)} — ${a.analysis_period.end.slice(0,10)}`}
function filtered(){return state.data.corridors.filter(c=>state.filter==='all'||c.status===state.filter)}
function renderList(){let rows=filtered();$('#corridor-list').innerHTML=rows.map((c,i)=>`<button class="corridor-row ${state.selected===c.id?'active':''}" data-id="${c.id}"><span class="rank">${String(i+1).padStart(2,'0')}</span><span><span class="row-title">${c.location_label||c.label}</span><span class="tag ${c.status}">${c.status}</span><span class="row-meta">${c.sample_count} traversals · ${c.day_count} days</span></span><span class="delta">${c.comparison?`+${fmt(c.comparison.difference_seconds)}s`:'—'}</span></button>`).join('');document.querySelectorAll('.corridor-row').forEach(b=>b.onclick=()=>{state.selected=b.dataset.id;renderList();renderDetail()});if(!state.selected&&rows[0]){state.selected=rows[0].id;renderList();renderDetail()}}
function drawMap(){
  const cs=state.data.corridors||[];
  const points=cs.flatMap(c=>c.geometry.coordinates.map(p=>[p[1],p[0]]));
  if(!points.length||!window.L)return;
  if(!state.leafletMap){
    state.leafletMap=L.map('map',{scrollWheelZoom:false,preferCanvas:true});
    L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'&copy; <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noreferrer">OpenStreetMap</a> contributors'}).addTo(state.leafletMap);
    state.leafletLayer=L.layerGroup().addTo(state.leafletMap);
  }
  state.leafletLayer.clearLayers();
  const bounds=[];
  cs.forEach(c=>{
    const coords=c.geometry.coordinates.map(p=>[p[1],p[0]]); coords.forEach(p=>bounds.push(p));
    const active=state.selected===c.id, supported=c.status==='supported';
    const line=L.polyline(coords,{color:supported?'#176b78':'#7b9a96',weight:active?8:supported?6:4,opacity:active?1:.78,lineCap:'round',lineJoin:'round'}).addTo(state.leafletLayer);
    line.bindPopup(`<strong>${c.location_label||c.label}</strong><br>${c.status} · ${c.sample_count} traversals · ${c.day_count} days${c.comparison?`<br>Peak–midday difference: +${fmt(c.comparison.difference_seconds)} seconds`:''}`);
    line.on('click',()=>{state.selected=c.id;renderList();renderDetail()});
    coords.forEach(p=>L.circleMarker(p,{radius:active?6:4,weight:2,color:'#fff',fillColor:supported?'#7ce0c3':'#c6d8d4',fillOpacity:1}).addTo(state.leafletLayer));
  });
  const focus=cs.find(c=>c.id===state.selected); const focusBounds=focus?focus.geometry.coordinates.map(p=>[p[1],p[0]]):bounds; state.leafletMap.invalidateSize(); if(focus){const center=L.latLngBounds(focusBounds).getCenter(); state.leafletMap.flyTo(center,15,{duration:.35});}else state.leafletMap.fitBounds(focusBounds,{padding:[42,42],maxZoom:12});
}
function renderDetail(){const c=state.data.corridors.find(x=>x.id===state.selected);if(!c)return;drawMap();const d=c.comparison?.difference_seconds||0;const pct=Math.max(10,Math.min(100,c.median_seconds/6));const tmss=c.tms_context?.matched_sites||[];const tms=tmss.map(s=>`${s.name} ${s.direction} · peak window ${fmt(s.peak_window_volume)} vehicles · ${s.days} days`).join('; ');const countss=c.count_station_context?.matched_stations||[];const counts=countss.map(s=>`${s.address} · AADT 2019 ${fmt(s.aadt2019)} · ${fmt(s.distance_m)}m away`).join('; ');const volumeDefault=c.comparison&&tmss[0]?.peak_window_volume?tmss[0].peak_window_volume:'';$('#detail').innerHTML=`<div class="detail-grid"><div class="detail-main"><div class="kicker">${c.id} · ${c.status.toUpperCase()}</div><h2>${c.location_label||c.label}</h2><p class="small">${c.note}</p><div class="metric-row"><div class="metric"><b>${fmt(c.median_seconds)}s</b><small>median traversal</small></div><div class="metric"><b>${c.comparison?`+${fmt(d)}s`:'—'}</b><small>peak vs midday</small></div><div class="metric"><b>${c.sample_count}</b><small>accepted traversals</small></div></div><div class="bars"><div class="bar-wrap"><div class="bar" style="height:${pct}%"></div><span class="bar-label">overall</span></div><div class="bar-wrap"><div class="bar mid" style="height:${Math.max(8,pct-d/4)}%"></div><span class="bar-label">midday reference</span></div></div><p class="small">Observed comparison only. It is not proven removable delay. Traffic counts shown here are context; they do not validate the sampled GPS as representative of all traffic.</p></div><div class="detail-side"><div class="kicker">EVIDENCE</div><h2>What this supports</h2><p class="small">${c.status==='supported'?'A repeated peak–midday difference is visible in the sampled history.':'The route has repeat observations, but not enough comparable windows for a supported peak comparison.'}</p><p class="small"><strong>Signal context:</strong> ${(c.nearby_signals||[]).map(s=>`${s.intersection} (${s.distance_m}m)`).join('; ')||'No supplied signal within 700m'}</p><p class="small"><strong>TMS context:</strong> ${tms||'No matched FDOT count site for this road name. This corridor remains unweighted.'}</p><p class="small"><strong>Count-station context:</strong> ${counts||'No nearby 2019 AADT station matched by road name.'} <span class="small">AADT is annual average traffic, not directional peak volume.</span></p><p class="small"><strong>Coverage months:</strong> ${(c.months||[]).join(', ')}</p><p class="small"><strong>Next verification:</strong> match the segment itself to the supplied StreetNetwork geometry, then review with a county engineer.</p><div class="scenario"><div class="kicker">SCENARIO CALCULATOR</div><h2>Test a reduction assumption</h2><p class="small scenario-baseline">Baseline: observed GPS peak–midday difference = <strong>${c.comparison?`+${fmt(d)} seconds`:'not available'}</strong>. Reductions apply only to this observed difference.</p><div class="scenario-grid"><div><label>Reduction</label><input id="fraction" type="number" min="0" max="100" value="20" /></div><div><label>Peak-window vehicles</label><input id="volume" type="number" min="0" value="${volumeDefault}" placeholder="required" /></div><div><label>Value of time ($/person-hr)</label><input id="vot" type="number" min="0" value="19.60" /></div></div><div class="scenario-result" id="scenario-result">Requires a supported GPS comparison and matched TMS volume.</div><p class="scenario-note">Illustrative only: this is not an accurate forecast because traffic volume, occupancy, costs, and treatment effectiveness are incomplete.</p></div></div></div>`;['fraction','volume','vot'].forEach(id=>$('#'+id).addEventListener('input',updateScenario));updateScenario()}
function updateScenario(){
  const c=state.data.corridors.find(x=>x.id===state.selected), f=Number($('#fraction')?.value||0)/100, q=Number($('#volume')?.value||0), v=Number($('#vot')?.value||0), d=c?.comparison?.difference_seconds||0;
  if(!d){$('#scenario-result').innerHTML='No qualifying GPS comparison is available for this corridor.';return}
  const saved=d*f;
  let html=`GPS baseline: <strong>${fmt(d)} seconds</strong> observed peak–midday difference.<br>Illustrative reduction: <strong>${fmt(saved)} seconds per vehicle</strong>.`;
  if(q&&v&&c?.tms_context?.matched_sites?.length){const annual=saved/3600*q*250*v*1.48;html+=`<br><br>Conditional annual person-time value: <strong>$${Math.round(annual).toLocaleString()}</strong><br><span class="small">Uses ${q.toLocaleString()} matched peak-window vehicles, 1.48 occupants/vehicle, 250 weekdays, and $${v.toFixed(2)}/person-hour.</span>`;}
  else html+=`<br><span class="small">Annual dollar value is unavailable until a matched peak-window volume and value-of-time assumption are supplied.</span>`;
  $('#scenario-result').innerHTML=html;
}
function download(){const c=state.data.corridors.find(x=>x.id===state.selected);const row={id:c.id,label:c.label,status:c.status,sample_count:c.sample_count,day_count:c.day_count,median_seconds:c.median_seconds,peak_midday_difference_seconds:c.comparison?.difference_seconds||'',note:c.note};const blob=new Blob([Object.keys(row).join(',')+'\n'+Object.values(row).map(v=>`"${String(v).replaceAll('"','""')}"`).join(',')],{type:'text/csv'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`${c.id}-summary.csv`;a.click();URL.revokeObjectURL(a.href)}
async function init(){try{const r=await fetch('analysis.json');state.data=await r.json();renderStats(state.data.quality_summary);drawMap();renderList();$('#filter').onchange=e=>{state.filter=e.target.value;state.selected=null;renderList();renderDetail()};$('#download').onclick=download}catch(e){$('#detail').innerHTML='<div class="empty"><h2>Dataset could not be loaded</h2><p>Run the local analysis pipeline to rebuild the sanitized data bundle.</p></div>'}}
init();

